+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("names case-insensitive", () => {
+  expect(nextRun("0 9 * jan mon", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T09:00:00.000Z");
+});
+
+test("month names", () => {
+  expect(nextRun("0 0 1 JAN *", at("2025-12-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:00:00.000Z");
+});
+
+test("step from value to end", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:05:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+});
+
+test("step star", () => {
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:15:00.000Z");
+});
+
+test("sunday as 7", () => {
+  expect(nextRun("0 8 * * 7", at("2026-01-03T09:00:00Z")).toISOString()).toBe("2026-01-04T08:00:00.000Z");
+});
+
+test("both dom and dow (or)", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2025-12-31T23:59:00Z")).toISOString()).toBe("2026-01-01T00:00:00.000Z");
+});
+
+test("feb 29 leap year", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+});
+
+test("never fires feb 30", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid step 0", () => {
+  expect(() => nextRun("*/0 * * * *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid backwards range", () => {
+  expect(() => nextRun("30-10 * * * *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid unknown name", () => {
+  expect(() => nextRun("0 0 * FOO *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid out of range", () => {
+  expect(() => nextRun("60 * * * *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("invalid step non-integer", () => {
+  expect(() => nextRun("*/1.5 * * * *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("dom full written 1-31", () => {
+  // dom full, dow restricted Monday => only Mondays
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+});
