diff -ruN --exclude=node_modules --exclude=.git a/csv.ts b/csv.ts
--- a/csv.ts	2026-11-01 17:25:12
+++ b/csv.ts	2026-11-01 17:27:41
@@ -50,3 +50,170 @@
   rows.push(row);
   return rows;
 }
+
+export class CsvStream {
+  private bomDone = false;
+  private row: string[] = [];
+  private pieces: string[] = [];
+  private fieldOpen = false;
+  private quoted = false;
+  private afterQuote = false;
+  private pendingCr = false;
+  private pendingAfterQuote = false;
+  private pendingQuote = false;
+
+  push(chunk: string): string[][] {
+    const result: string[][] = [];
+    if (!this.bomDone && chunk.length > 0) {
+      if (chunk.charCodeAt(0) === 0xfeff) chunk = chunk.slice(1);
+      this.bomDone = true;
+    }
+    this.process(chunk, result);
+    return result;
+  }
+
+  end(): string[][] {
+    const result: string[][] = [];
+    if (this.pendingCr) {
+      if (this.pendingAfterQuote) {
+        throw new SyntaxError("unexpected \\r after a closing quote");
+      }
+      this.pieces.push("\r");
+      this.fieldOpen = true;
+      this.pendingCr = false;
+      this.pendingAfterQuote = false;
+    }
+    if (this.pendingQuote) {
+      this.quoted = false;
+      this.afterQuote = true;
+      this.pendingQuote = false;
+    }
+    if (this.quoted) {
+      throw new SyntaxError("a quoted field is still open at the end of the input");
+    }
+    if (this.row.length > 0 || this.fieldOpen) {
+      this.finalizeField();
+      result.push(this.row);
+      this.row = [];
+    }
+    return result;
+  }
+
+  private finalizeField(): void {
+    const value = this.fieldOpen ? this.pieces.join("") : "";
+    this.row.push(value);
+    this.pieces = [];
+    this.fieldOpen = false;
+    this.quoted = false;
+    this.afterQuote = false;
+  }
+
+  private process(chunk: string, result: string[][]): void {
+    let j = 0;
+    const len = chunk.length;
+    if (this.pendingQuote && len > 0) {
+      if (chunk.charCodeAt(0) === 34) {
+        this.pieces.push('"');
+        j = 1;
+        this.pendingQuote = false;
+      } else {
+        this.quoted = false;
+        this.afterQuote = true;
+        this.pendingQuote = false;
+      }
+    }
+    while (j < len) {
+      if (this.pendingCr) {
+        const c = chunk[j];
+        if (c === "\n") {
+          j++;
+          this.finalizeField();
+          result.push(this.row);
+          this.row = [];
+          this.pieces = [];
+          this.fieldOpen = false;
+          this.pendingCr = false;
+          this.pendingAfterQuote = false;
+        } else {
+          if (this.pendingAfterQuote) {
+            throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+          }
+          this.pieces.push("\r");
+          this.fieldOpen = true;
+          this.pendingCr = false;
+        }
+        continue;
+      }
+      if (this.quoted) {
+        const idx = chunk.indexOf('"', j);
+        if (idx === -1) {
+          this.pieces.push(chunk.slice(j));
+          j = len;
+        } else {
+          if (idx > j) this.pieces.push(chunk.slice(j, idx));
+          j = idx;
+          if (j + 1 < len && chunk[j + 1] === '"') {
+            this.pieces.push('"');
+            j += 2;
+          } else if (j + 1 < len) {
+            j += 1;
+            this.quoted = false;
+            this.afterQuote = true;
+          } else {
+            j += 1;
+            this.pendingQuote = true;
+          }
+        }
+        continue;
+      }
+      if (this.afterQuote) {
+        const c = chunk[j++];
+        if (c === ",") {
+          this.finalizeField();
+        } else if (c === "\n") {
+          this.finalizeField();
+          result.push(this.row);
+          this.row = [];
+          this.pieces = [];
+          this.fieldOpen = false;
+        } else if (c === "\r") {
+          this.pendingCr = true;
+          this.pendingAfterQuote = true;
+        } else {
+          throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+        }
+        continue;
+      }
+      let start = j;
+      while (j < len) {
+        const ch = chunk[j];
+        if (ch === "," || ch === "\n" || ch === "\r" || ch === '"') break;
+        j++;
+      }
+      if (j > start) {
+        this.pieces.push(chunk.slice(start, j));
+        this.fieldOpen = true;
+      }
+      if (j >= len) break;
+      const c = chunk[j++];
+      if (c === '"') {
+        if (this.fieldOpen) {
+          throw new SyntaxError(`a quote in a field that is not quoted`);
+        }
+        this.quoted = true;
+        this.fieldOpen = true;
+      } else if (c === ",") {
+        this.finalizeField();
+      } else if (c === "\n") {
+        this.finalizeField();
+        result.push(this.row);
+        this.row = [];
+        this.pieces = [];
+        this.fieldOpen = false;
+      } else if (c === "\r") {
+        this.pendingCr = true;
+        this.pendingAfterQuote = false;
+      }
+    }
+  }
+}

