+import { expect, test } from "bun:test";
+import { runPool } from "./pool";
+
+const later = <T>(ms: number, v: T) => () => new Promise<T>((r) => setTimeout(() => r(v), ms));
+
+test("never exceeds the concurrency limit", async () => {
+  let cur = 0, max = 0;
+  const tasks = Array.from({ length: 20 }, () => async () => {
+    cur++; max = Math.max(max, cur);
+    await new Promise((r) => setTimeout(r, 5));
+    cur--;
+    return 1;
+  });
+  await runPool(tasks, 4);
+  expect(max).toBeLessThanOrEqual(4);
+});
+
+test("results are in input order", async () => {
+  const tasks = [() => new Promise((r) => setTimeout(() => r("slow"), 20)), () => "fast"];
+  const out = await runPool(tasks, 2);
+  expect(out.map((r) => (r.status === "fulfilled" ? r.value : undefined))).toEqual(["slow", "fast"]);
+});
+
+test("retries the configured number of times", async () => {
+  let calls = 0;
+  const out = await runPool([() => { calls++; if (calls <= 2) throw new Error("boom"); return "ok"; }], 1, { retries: 2 });
+  expect(calls).toBe(3);
+  expect(out[0].attempts).toBe(3);
+  expect(out[0].status).toBe("fulfilled");
+});
+
+test("no retry when retries is 0", async () => {
+  let calls = 0;
+  const out = await runPool([() => { calls++; throw new Error("boom"); }], 1);
+  expect(calls).toBe(1);
+  expect(out[0].attempts).toBe(1);
+  expect(out[0].status).toBe("rejected");
+});
+
+test("sync throw and non-promise return", async () => {
+  const out = await runPool([() => { throw new Error("sync"); }, () => 7], 2);
+  expect(out[0].status).toBe("rejected");
+  expect(out[1].status).toBe("fulfilled");
+  if (out[1].status === "fulfilled") expect(out[1].value).toBe(7);
+});
+
+test("limit validation", async () => {
+  await expect(runPool([() => 1], 0)).rejects.toBeInstanceOf(RangeError);
+  await expect(runPool([() => 1], 1.5)).rejects.toBeInstanceOf(RangeError);
+  await expect(runPool([() => 1], Infinity, { retries: 1.5 })).rejects.toBeInstanceOf(RangeError);
+});
+
+test("retries validation", async () => {
+  await expect(runPool([() => 1], 1, { retries: -1 })).rejects.toBeInstanceOf(RangeError);
+  await expect(runPool([() => 1], 1, { retries: 1.5 })).rejects.toBeInstanceOf(RangeError);
+});
+
+test("already aborted starts no task", async () => {
+  let called = false;
+  const ac = new AbortController();
+  ac.abort("nope");
+  const out = await runPool([() => { called = true; return 1; }], 1, { signal: ac.signal });
+  expect(called).toBe(false);
+  expect(out[0]).toEqual({ status: "rejected", reason: "nope", attempts: 0 });
+});
+
+test("abort stops starting new tasks", async () => {
+  const ac = new AbortController();
+  let started = 0;
+  const tasks = Array.from({ length: 6 }, () => () => new Promise<number>((r) => {
+    started++;
+    setTimeout(() => r(1), 20);
+  }));
+  setTimeout(() => ac.abort(new Error("stop")), 5);
+  const out = await runPool(tasks, 2, { signal: ac.signal });
+  expect(out.filter((r) => r.attempts === 0).length).toBeGreaterThan(0);
+});
+
+test("in-flight task keeps its result after abort", async () => {
+  const ac = new AbortController();
+  setTimeout(() => ac.abort(new Error("stop")), 5);
+  const out = await runPool([() => new Promise<string>((r) => setTimeout(() => r("done"), 20))], 1, { signal: ac.signal });
+  expect(out[0]).toEqual({ status: "fulfilled", value: "done", attempts: 1 });
+});
+
+test("cancelled retry settles with signal.reason and attempts", async () => {
+  const ac = new AbortController();
+  let calls = 0;
+  const task = () => new Promise<string>((_r, rej) => {
+    calls++;
+    setTimeout(() => rej(new Error("fail")), 5);
+  });
+  setTimeout(() => ac.abort(new Error("cancel")), 2);
+  const out = await runPool([task], 1, { retries: 5, signal: ac.signal });
+  expect(out[0].status).toBe("rejected");
+  expect(out[0].attempts).toBe(1);
+  if (out[0].status === "rejected") expect((out[0].reason as Error).message).toBe("cancel");
+});

