+import { expect, test } from "bun:test";
+import { distinctInWindow } from "./window";
+
+test("out-of-order events are counted by time", () => {
+  const events = [
+    { t: 8, key: "a" },
+    { t: 0, key: "a" },
+    { t: 5, key: "b" },
+    { t: 20, key: "c" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([2, 1, 2, 1]);
+});
+
+test("boundary: time exactly t - windowMs is excluded", () => {
+  const events = [
+    { t: 0, key: "a" },
+    { t: 10, key: "b" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([1, 1]);
+});
+
+test("boundary: time equal to t is included", () => {
+  const events = [
+    { t: 5, key: "a" },
+    { t: 5, key: "b" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([2, 2]);
+});
+
+test("duplicate keys collapse", () => {
+  const events = [
+    { t: 1, key: "a" },
+    { t: 2, key: "a" },
+    { t: 3, key: "a" },
+  ];
+  expect(distinctInWindow(events, 10)).toEqual([1, 1, 1]);
+});
+
+test("large window covers all events", () => {
+  const events = [
+    { t: 0, key: "a" },
+    { t: 100, key: "b" },
+    { t: 200, key: "c" },
+  ];
+  expect(distinctInWindow(events, 1000)).toEqual([1, 2, 3]);
+});
+
