diff -ruN --exclude=node_modules --exclude=.git a/src/core/trust/slop.ts b/src/core/trust/slop.ts
--- a/src/core/trust/slop.ts	1970-01-01 07:00:00
+++ b/src/core/trust/slop.ts	2026-11-01 17:36:45
@@ -0,0 +1,132 @@
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+function isTestPath(path: string): boolean {
+  const base = path.split('/').pop() ?? path;
+  if (/\.test\./.test(base)) return true;
+  if (/\.spec\./.test(base)) return true;
+  if (/_test\./.test(base)) return true;
+  if (/^test_/.test(base)) return true;
+  if (/(^|\/)(tests?|spec)\//.test(path)) return true;
+  return false;
+}
+
+function isDoc(path: string): boolean {
+  return /\.(md|markdown|txt|rst|adoc|json|ya?ml|toml|lock|csv)$/i.test(path);
+}
+
+function isAssertionLine(line: string): boolean {
+  return /\b(assert|expect|should|toBe|toEqual|toContain|toThrow|assertEqual|assert\.)/i.test(line.trim());
+}
+
+function isWeakeningLine(line: string): boolean {
+  const t = line.trim().toLowerCase();
+  return t === 'pass' || t === '...' || /\.skip\b|\bxit\b|\bxtest\b/i.test(line);
+}
+
+function isSkipLine(line: string): boolean {
+  return /\.skip\b|\bxit\b|\bxtest\b|\bSkip\s*\(|@pytest\.mark\.skip|pytest\.skip/i.test(line);
+}
+
+function isSuppression(line: string): boolean {
+  const parts = ['@ts-' + 'ignore', '@ts-' + 'nocheck', '@ts-' + 'expect-error', 'eslint' + '-disable', 'type:' + '\\s*ignore', '#' + '\\s*noqa', 'istanbul' + ' ignore', 'c8' + ' ignore', 'pragma:' + '\\s*no cover'];
+  return new RegExp(parts.join('|'), 'i').test(line);
+}
+
+function isSwallowed(line: string): boolean {
+  return /catch\b[^{]*\{\s*\}/.test(line) || /except\b[^:]*:\s*pass\b/.test(line);
+}
+
+function isTypeEscape(line: string): boolean {
+  return /\bas any\b/.test(line);
+}
+
+function isStub(line: string): boolean {
+  const l = line.toLowerCase();
+  const a = 'not' + ' implemented';
+  const b = 'notimplemented' + 'error';
+  const c = 'unimplement' + 'ed';
+  return l.includes(a) || l.includes(b) || l.includes(c);
+}
+
+function isWeakened(c: FileChange): boolean {
+  const removedAsserts = c.removed.filter(isAssertionLine);
+  if (removedAsserts.length === 0) return false;
+  if (c.added.some(isWeakeningLine)) return true;
+  const addedAsserts = c.added.filter(isAssertionLine);
+  return addedAsserts.length < removedAsserts.length;
+}
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    if (c.deleted) {
+      if (isTestPath(c.path)) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (isTestPath(c.path)) {
+      for (const line of c.added) {
+        if (isSkipLine(line)) out.push({ rule: 'test-skipped', path: c.path, line: line.trim() });
+      }
+      if (isWeakened(c)) {
+        const line = c.added.find((l) => l.trim() === 'pass') ?? c.removed.find(isAssertionLine) ?? c.added[0];
+        out.push({ rule: 'test-weakened', path: c.path, line: line?.trim() });
+      }
+    }
+    if (!isDoc(c.path)) {
+      for (const line of c.added) {
+        const t = line.trim();
+        if (isSuppression(line)) out.push({ rule: 'suppression', path: c.path, line: t });
+        if (isSwallowed(line)) out.push({ rule: 'swallowed-error', path: c.path, line: t });
+        if (isTypeEscape(line)) out.push({ rule: 'type-escape', path: c.path, line: t });
+        if (isStub(line)) out.push({ rule: 'stub', path: c.path, line: t });
+      }
+    }
+  }
+  return out;
+}
+
+export function formatSlop(f: SlopFinding): string {
+  return f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`;
+}
+
+export function changesFromPatch(patch: string): FileChange[] {
+  const lines = patch.split('\n');
+  const result: FileChange[] = [];
+  let current: FileChange | null = null;
+  let deleted = false;
+  let oldPath: string | undefined;
+  for (const line of lines) {
+    if (line.startsWith('diff --git ')) {
+      if (current) result.push(current);
+      current = null;
+      deleted = false;
+      oldPath = undefined;
+      continue;
+    }
+    if (line.startsWith('deleted file mode')) {
+      deleted = true;
+      continue;
+    }
+    if (line.startsWith('--- ')) {
+      const m = line.match(/^--- (?:a\/)?(.*)$/);
+      const p = m?.[1];
+      oldPath = p && p !== '/dev/null' ? p : oldPath;
+      continue;
+    }
+    if (line.startsWith('+++ ')) {
+      const m = line.match(/^\+\+\+ (?:b\/)?(.*)$/);
+      let p = m?.[1];
+      if (p === '/dev/null') p = oldPath;
+      current = { path: p ?? '', added: [], removed: [], deleted };
+      continue;
+    }
+    if (!current) continue;
+    if (line.startsWith('@@')) continue;
+    if (line.startsWith('+') && !line.startsWith('+++')) current.added.push(line.slice(1));
+    else if (line.startsWith('-') && !line.startsWith('---')) current.removed.push(line.slice(1));
+  }
+  if (current) result.push(current);
+  return result;
+}
