@@ -0,0 +1,14 @@
+import type { ModelSpec } from '../types.ts';
+
+export const HANDOFF_PROMPT =
+  'Your context is getting large. Write a handoff note for the next session: what you did, what is left, and the exact next step. Reply with only the note; no tool calls.';
+
+export const HANDOFF_NO_TOOLS =
+  'not run: this turn is a handoff; reply with the handoff note instead of calling tools.';
+
+export function defaultHandoffAt(model: ModelSpec): number {
+  const half = Math.floor(model.caps.contextWindow / 2);
+  let at = Math.min(half, 150_000);
+  if (model.price.above) at = Math.min(at, Math.floor(model.price.above.tokens * 0.9));
+  return at;
+}
