@@ -0,0 +1,130 @@
+import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from 'node:fs';
+import { join } from 'node:path';
+
+export type ThreadSession = { sessionId: string; model: string; role: string; why: string };
+export type ThreadMessage = { id: string; from: string; text: string };
+export type ThreadHandoff = { sessionId: string; note: string };
+export type ThreadState = 'working' | 'done' | 'failed';
+
+export type Thread = {
+  id: string;
+  title: string;
+  task: string;
+  state: ThreadState;
+  result?: string;
+  handoff?: ThreadHandoff;
+  sessions: ThreadSession[];
+  messages: ThreadMessage[];
+  pending: ThreadMessage[];
+};
+
+type ThreadEvent =
+  | { kind: 'task'; task: string }
+  | { kind: 'session'; sessionId: string; model: string; role: string; why: string }
+  | { kind: 'handoff'; sessionId: string; note: string }
+  | { kind: 'message'; id: string; from: string; text: string }
+  | { kind: 'delivered'; ids: string[]; sessionId: string }
+  | { kind: 'state'; state: ThreadState; result?: string };
+
+export function titleOf(task: string): string {
+  const line = ((task ?? '').trim().split(/\n/)[0] ?? '').trim();
+  if (line.length <= 60) return line;
+  return line.slice(0, 57) + '...';
+}
+
+export function threadsDir(home: string, slug: string): string {
+  return join(home, 'projects', slug, 'threads');
+}
+
+export function foldThread(id: string, events: ThreadEvent[]): Thread {
+  let task = '';
+  const sessions: ThreadSession[] = [];
+  let handoff: ThreadHandoff | undefined;
+  const messages: ThreadMessage[] = [];
+  const delivered = new Set<string>();
+  let state: ThreadState = 'working';
+  let result: string | undefined;
+  for (const e of events) {
+    switch (e.kind) {
+      case 'task':
+        task = e.task;
+        break;
+      case 'session':
+        sessions.push({ sessionId: e.sessionId, model: e.model, role: e.role, why: e.why });
+        break;
+      case 'handoff':
+        handoff = { sessionId: e.sessionId, note: e.note };
+        break;
+      case 'message':
+        messages.push({ id: e.id, from: e.from, text: e.text });
+        break;
+      case 'delivered':
+        for (const i of e.ids) delivered.add(i);
+        break;
+      case 'state':
+        state = e.state;
+        if (e.result !== undefined) result = e.result;
+        break;
+    }
+  }
+  const pending = messages.filter((m) => !delivered.has(m.id));
+  return { id, title: titleOf(task), task, state, ...(result !== undefined ? { result } : {}), ...(handoff ? { handoff } : {}), sessions, messages, pending };
+}
+
+const ID_RE = /^t-[0-9a-f]{8}$/;
+
+export class ThreadStore {
+  private dir: string;
+  constructor(dir: string) {
+    this.dir = dir;
+    mkdirSync(dir, { recursive: true });
+  }
+  private path(id: string): string {
+    return join(this.dir, `${id}.jsonl`);
+  }
+  private readEvents(id: string): ThreadEvent[] {
+    const p = this.path(id);
+    if (!existsSync(p)) return [];
+    const lines = readFileSync(p, 'utf8').split('\n').filter(Boolean);
+    return lines.map((l) => JSON.parse(l) as ThreadEvent);
+  }
+  private appendRaw(id: string, event: ThreadEvent): void {
+    appendFileSync(this.path(id), JSON.stringify(event) + '\n');
+  }
+  has(id: string): boolean {
+    if (!ID_RE.test(id)) return false;
+    return existsSync(this.path(id));
+  }
+  open(task: string): string {
+    const id = `t-${crypto.randomUUID().replace(/-/g, '').slice(0, 8)}`;
+    mkdirSync(this.dir, { recursive: true });
+    this.appendRaw(id, { kind: 'task', task });
+    return id;
+  }
+  append(id: string, event: ThreadEvent | Record<string, unknown>): void {
+    if (!ID_RE.test(id)) throw new Error('not a thread id');
+    if (!this.has(id)) throw new Error(`no thread ${id}`);
+    this.appendRaw(id, event as ThreadEvent);
+  }
+  send(id: string, from: string, text: string): string {
+    if (!ID_RE.test(id)) throw new Error('not a thread id');
+    if (!this.has(id)) throw new Error(`no thread ${id}`);
+    const msgId = crypto.randomUUID();
+    this.appendRaw(id, { kind: 'message', id: msgId, from, text });
+    return msgId;
+  }
+  read(id: string): Thread {
+    if (!ID_RE.test(id)) throw new Error('not a thread id');
+    if (!this.has(id)) throw new Error(`no thread ${id}`);
+    return foldThread(id, this.readEvents(id));
+  }
+  list(): Thread[] {
+    if (!existsSync(this.dir)) return [];
+    const ids = readdirSync(this.dir)
+      .filter((f) => f.endsWith('.jsonl'))
+      .map((f) => f.replace(/\.jsonl$/, ''))
+      .filter((id) => ID_RE.test(id));
+    const threads = ids.map((id) => foldThread(id, this.readEvents(id)));
+    return threads.sort((a, b) => a.id.localeCompare(b.id));
+  }
+}
