+import type { JsonObject, ToolDef, ToolOutput } from '../types.ts';
+import type { ToolSpec } from './registry.ts';
+import type { ThreadStore } from '../project/threads.ts';
+
+export type RecallSession = { id: string; events: () => any[] };
+
+export function recallTool(sessions: () => RecallSession[]): ToolSpec {
+  const def: ToolDef = {
+    name: 'recall',
+    description: 'Search prior session logs of this project for text.',
+    schema: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] },
+  };
+  return {
+    ...def,
+    effect: 'read',
+    replay: 'safe',
+    run: async (input: JsonObject): Promise<ToolOutput> => {
+      const query = String(input.query ?? '');
+      if (!query) return { text: 'query is required', isError: true };
+      let re: RegExp;
+      let literal = false;
+      try {
+        re = new RegExp(query);
+      } catch {
+        re = new RegExp(escapeRe(query));
+        literal = true;
+      }
+      const sess = sessions();
+      const hits: string[] = [];
+      let count = 0;
+      sess.forEach((s, si) => {
+        const evs = s.events();
+        const toolNameByCall = new Map<string, string>();
+        for (const e of evs) {
+          if (e.kind === 'assistant') for (const b of e.blocks ?? []) if (b.type === 'tool_use') toolNameByCall.set(b.callId ?? b.id, b.name);
+        }
+        for (const e of evs) {
+          if (e.kind === 'tool_result') {
+            const text = e.output?.text ?? '';
+            if (re.test(text)) {
+              count++;
+              const name = toolNameByCall.get(e.callId) ?? 'tool';
+              hits.push(`[session ${si + 1} of ${sess.length} · result ${name}] ${text}`);
+            }
+            re.lastIndex = 0;
+          } else if (e.kind === 'assistant') {
+            for (const b of e.blocks ?? []) {
+              if (b.type === 'tool_use') {
+                const hay = `${b.name} ${JSON.stringify(b.input ?? {})}`;
+                if (re.test(hay)) {
+                  count++;
+                  hits.push(`[session ${si + 1} of ${sess.length} · call ${b.name}] ${b.name} ${JSON.stringify(b.input ?? {})}`);
+                }
+                re.lastIndex = 0;
+              } else if (b.type === 'text') {
+                if (re.test(b.text ?? '')) {
+                  count++;
+                  hits.push(`[session ${si + 1} of ${sess.length} · assistant] ${b.text}`);
+                }
+                re.lastIndex = 0;
+              }
+            }
+          } else if (e.kind === 'user') {
+            if (re.test(e.text ?? '')) {
+              count++;
+              hits.push(`[session ${si + 1} of ${sess.length} · user] ${e.text}`);
+            }
+            re.lastIndex = 0;
+          }
+        }
+      });
+      if (count === 0) return { text: 'no match', isError: false };
+      return { text: `${count} match${count === 1 ? '' : 'es'}\n${hits.join('\n')}`, isError: false };
+    },
+  };
+}
+
+function escapeRe(s: string): string {
+  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+}
+
+export function threadTools(store: ThreadStore, me: string): ToolSpec[] {
+  const listTool: ToolSpec = {
+    name: 'threads',
+    description: 'List the other threads in this project.',
+    schema: { type: 'object', properties: {} },
+    effect: 'read',
+    replay: 'safe',
+    run: async (): Promise<ToolOutput> => {
+      const others = store.list().filter((t) => t.id !== me);
+      if (!others.length) return { text: '(no other threads)', isError: false };
+      const lines = others.map((t) => `${t.id} ${t.title} [${t.state}]${t.handoff ? `\n  handoff: ${t.handoff.note}` : ''}`);
+      return { text: lines.join('\n'), isError: false };
+    },
+  };
+  const readTool: ToolSpec = {
+    name: 'read_thread',
+    description: 'Read another thread.',
+    schema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] },
+    effect: 'read',
+    replay: 'safe',
+    run: async (input: JsonObject): Promise<ToolOutput> => {
+      const id = String(input.id ?? '');
+      if (!store.has(id)) return { text: `no thread ${id}`, isError: true };
+      const t = store.read(id);
+      const parts: string[] = [];
+      parts.push(`<task>\n${t.task}\n</task>`);
+      if (t.handoff) parts.push(`<handoff session="${t.handoff.sessionId}">\n${t.handoff.note}\n</handoff>`);
+      parts.push(`state: ${t.state}${t.result ? ` (${t.result})` : ''}`);
+      return { text: parts.join('\n'), isError: false };
+    },
+  };
+  const sendTool: ToolSpec = {
+    name: 'message_thread',
+    description: 'Send a message to another thread.',
+    schema: { type: 'object', properties: { id: { type: 'string' }, text: { type: 'string' } }, required: ['id', 'text'] },
+    effect: 'write_workspace',
+    replay: 'unsafe',
+    run: async (input: JsonObject): Promise<ToolOutput> => {
+      const id = String(input.id ?? '');
+      const text = String(input.text ?? '');
+      if (id === me) return { text: 'cannot message this thread', isError: true };
+      if (!store.has(id)) return { text: `no thread ${id}`, isError: true };
+      store.send(id, me, text);
+      return { text: `sent to ${id}`, isError: false };
+    },
+  };
+  return [listTool, readTool, sendTool];
+}
