diff -ruN --exclude=node_modules --exclude=.git a/test/fixes.test.ts b/test/fixes.test.ts
--- a/test/fixes.test.ts	1970-01-01 07:00:00
+++ b/test/fixes.test.ts	2026-11-01 17:38:35
@@ -0,0 +1,40 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+describe('pricing fixes', () => {
+  test('bulk discount applies at exactly 10 units', () => {
+    const t = totals(cart('US', [['MUG', 10]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0].discount).toBe(225);
+    expect(t.subtotal).toBe(4275);
+  });
+
+  test('bulk discount applies highest tier at exactly 50 units', () => {
+    const t = totals(cart('US', [['MUG', 50]]));
+    expect(t.lines[0].discount).toBe(2250);
+    expect(t.subtotal).toBe(20250);
+  });
+
+  test('same-SKU lines merge before bulk pricing', () => {
+    const t = totals(cart('US', [['MUG', 5], ['MUG', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0].quantity).toBe(10);
+    expect(t.lines[0].discount).toBe(225);
+    expect(t.subtotal).toBe(4275);
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    const t = totals(cart('UK', [['BAG', 2]]));
+    expect(t.subtotal).toBe(4400);
+    expect(t.shipping).toBe(0);
+  });
+
+  test('shipping threshold uses discounted subtotal after coupon', () => {
+    const t = totals(cart('US', [['BAG', 2], ['MUG', 2]], 'FLAT5'));
+    expect(t.subtotal).toBe(5300);
+    expect(t.coupon).toBe(500);
+    expect(t.shipping).toBe(800);
+    expect(t.total).toBe(5992);
+  });
+});

