 //
 // formatDuration: milliseconds to the shortest text using d, h, m, s and ms, largest unit first, zero parts
 // left out, no spaces: 5_400_000 -> "1h30m", 1_500 -> "1s500ms", 0 -> "0s". Throws on a negative number.
+const UNIT_MS: Record<string, number> = {
+  d: 86_400_000,
+  h: 3_600_000,
+  m: 60_000,
+  s: 1_000,
+  ms: 1,
+};
+
+const PART_RE = /^\s*(?:\d+(?:\.\d+)?(?:ms|[dhms]))(?:\s*\d+(?:\.\d+)?(?:ms|[dhms]))*\s*$/;
+const SPLIT_RE = /(\d+(?:\.\d+)?)(ms|[dhms])/g;
+
 export function parseDuration(text: string): number {
-  throw new Error('not implemented');
+  if (!PART_RE.test(text)) {
+    throw new Error(`invalid duration: "${text}"`);
+  }
+  let total = 0;
+  SPLIT_RE.lastIndex = 0;
+  let m: RegExpExecArray | null;
+  while ((m = SPLIT_RE.exec(text)) !== null) {
+    total += parseFloat(m[1]) * UNIT_MS[m[2]];
+  }
+  return Math.round(total);
 }

 export function formatDuration(ms: number): string {
-  throw new Error('not implemented');
+  if (ms < 0) throw new Error('duration must not be negative');
+  if (ms === 0) return '0s';
+  const units = [
+    { u: 'd', n: 86_400_000 },
+    { u: 'h', n: 3_600_000 },
+    { u: 'm', n: 60_000 },
+    { u: 's', n: 1_000 },
+    { u: 'ms', n: 1 },
+  ];
+  let r = ms;
+  const counts: number[] = [];
+  for (const { n } of units) {
+    counts.push(Math.floor(r / n));
+    r = r % n;
+  }
+  let out = '';
+  for (let i = 0; i < units.length; i++) {
+    if (counts[i] !== 0) {
+      out += `${counts[i]}${units[i].u}`;
+    }
+  }
+  if (out === '') out = '0s';
+  return out;
 }
