+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+
+test('parse more', () => {
+  expect(parseDuration('2d 4h')).toBe(187200000);
+  expect(parseDuration('1.5h')).toBe(5400000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1h30m')).toBe(5400000);
+});
+
+test('parse invalid messages', () => {
+  for (const bad of ['', '10', '5x', 'h', '-1s']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('format more', () => {
+  expect(formatDuration(1500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(3600500)).toBe('1h500ms');
+  expect(() => formatDuration(-1)).toThrow();
+});
