+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+test('lru basic', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('c', 3);
+  expect(cache.get('a')).toBeUndefined();
+  expect(cache.keys()).toEqual(['c', 'b']);
+  t = 1000;
+  expect(cache.get('b')).toBeUndefined();
+});
+
+test('lru delete', () => {
+  let t = 0;
+  const ev: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (k, v, r) => ev.push([k, v, r]);
+  cache.set('a', 1);
+  t = 200;
+  expect(cache.delete('a')).toBe(false);
+  expect(ev).toEqual([['a', 1, 'expired']]);
+});
